import argparse
import os
import csv
import sys

# This script extracts records from the demultiplexing reports generated by simple_demux.py for a specified list of ZMWs, and compiles them into a single CSV file.
# Usage: python extract_from_demux_report.py sharing_details.csv <demux_report1.csv> <demux_report2.csv> ...
# (sharing_details.csv is produced by dupes_in_non_kinnex_samples.py)

found_recs = []

wanted_ids = []
zmw_to_umi = {}

with open(sys.argv[1], 'r', newline = '') as csvfile:
    reader = csv.DictReader(csvfile)
    for row in reader:
        wanted_ids.append(row['zmw'])
        zmw_to_umi[row['zmw']] = row['umi']

wanted_ids = set(wanted_ids)

print(f'identified {len(wanted_ids)} wanted records')

for reportfile in sys.argv[2:]:
    print(f'Scanning {reportfile}') 
    with open(reportfile, 'r', newline = '') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            if row['ZMW'] in wanted_ids:
                found_recs.append({'umi': zmw_to_umi[row['ZMW']]} | row)
                

headers = list(found_recs[0].keys())
with open("sharing_report_recs.csv", "w", newline="") as csvfile:
    writer = csv.DictWriter(csvfile, fieldnames=headers)
    writer.writeheader()
    for row in found_recs:
        writer.writerow(row)

